 @Test public void interruptedReadyRecoveryResumesInstalledFilesIdempotentlyBeforeControllerLoad()throws Exception {
  Context source=appFolderFixture("crash-source"),fresh=appFolderFixture("crash-fresh");try{NotesRepository repo=new NotesRepository(source);Note note=Note.create(1).edit("Crash safe","Original checkpoint",2);repo.save(Collections.singletonList(note));repo.selectFolder(tree,Collections.singletonList(note));AppFolder folder=new AppFolder(source,tree);folder.save();AppFolder.Checkpoint checkpoint=folder.inspect();Uri saved=DocumentsContract.buildDocumentUriUsingTree(tree,rootId+"/Recovery/Checkpoints/checkpoint-"+checkpoint.id+".json");org.json.JSONObject envelope;try(java.io.InputStream in=context.getContentResolver().openInputStream(saved)){envelope=new org.json.JSONObject(new String(LocalOpenFile.bounded(in,8*1024*1024),java.nio.charset.StandardCharsets.UTF_8));}org.json.JSONObject manifest=new org.json.JSONObject(envelope.getString("payload"));java.io.File stage=new java.io.File(fresh.getFilesDir(),"app-folder-recovery-v1");assertTrue(stage.mkdir());org.json.JSONArray files=manifest.getJSONArray("files");
   for(int i=0;i<files.length();i++){org.json.JSONObject entry=files.getJSONObject(i);java.io.File target=new java.io.File(stage,"files/"+entry.getString("path"));if(entry.getBoolean("directory")){assertTrue(target.mkdirs());continue;}assertTrue(target.getParentFile().mkdirs() || target.getParentFile().isDirectory());Uri object=DocumentsContract.buildDocumentUriUsingTree(tree,rootId+"/Recovery/Objects/"+entry.getString("sha256")+".bin");try(java.io.InputStream in=context.getContentResolver().openInputStream(object);java.io.OutputStream out=new java.io.FileOutputStream(target)){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);}}
   org.json.JSONObject transaction=new org.json.JSONObject().put("tree",tree.toString()).put("manifest",manifest);java.nio.file.Files.write(new java.io.File(stage,"ready.json").toPath(),transaction.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));java.io.File alreadyInstalled=new java.io.File(fresh.getFilesDir(),"notes-library/library-v1.json");assertTrue(alreadyInstalled.getParentFile().mkdirs());assertTrue(new java.io.File(stage,"files/notes-library/library-v1.json").renameTo(alreadyInstalled));AppFolder.finishRecovery(fresh);AppFolder.finishRecovery(fresh);assertTrue(app.space.notes.domain.NoteMerge.same(note,new NotesRepository(fresh).load().get(0)));assertFalse(stage.exists());
  }finally{clearAppFolderFixture(source);clearAppFolderFixture(fresh);}
 }
 @Test public void checksumValidButUnsafeCheckpointPathsAreRejectedBeforeStaging()throws Exception {
  Context source=appFolderFixture("unsafe-source"),fresh=appFolderFixture("unsafe-fresh");try{NotesRepository repo=new NotesRepository(source);Note note=Note.create(1).edit("Safe","Owned destinations only",2);repo.save(Collections.singletonList(note));repo.selectFolder(tree,Collections.singletonList(note));AppFolder folder=new AppFolder(source,tree);folder.save();AppFolder.Checkpoint checkpoint=folder.inspect();Uri saved=DocumentsContract.buildDocumentUriUsingTree(tree,rootId+"/Recovery/Checkpoints/checkpoint-"+checkpoint.id+".json");org.json.JSONObject original;try(java.io.InputStream in=context.getContentResolver().openInputStream(saved)){original=new org.json.JSONObject(new String(LocalOpenFile.bounded(in,8*1024*1024),java.nio.charset.StandardCharsets.UTF_8));}org.json.JSONObject manifest=new org.json.JSONObject(original.getString("payload"));String id=UUID.randomUUID().toString();manifest.put("id",id).put("parent",checkpoint.id);manifest.getJSONArray("files").getJSONObject(0).put("path","../outside-owned-storage.json");String payload=manifest.toString();org.json.JSONObject attack=new org.json.JSONObject().put("payload",payload).put("sha256",GenerationProtocol.digest(payload.getBytes(java.nio.charset.StandardCharsets.UTF_8)));Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,rootId+"/Recovery/Checkpoints");Uri file=DocumentsContract.createDocument(context.getContentResolver(),parent,"application/json","checkpoint-"+id+".json");try(java.io.OutputStream out=context.getContentResolver().openOutputStream(file,"w")){out.write(attack.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}try{new AppFolder(fresh,tree).prepareRecovery();fail("Checksum alone does not make arbitrary destinations safe");}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("Unsafe"));}assertFalse(new java.io.File(fresh.getFilesDir(),"app-folder-recovery-v1").exists());assertTrue(new NotesRepository(fresh).localSnapshot().isEmpty());
  }finally{clearAppFolderFixture(source);clearAppFolderFixture(fresh);}
 }
